test.each([
  ["/Pattern", "cs", "sc"],
  ["/Pattern", "CS", "SC"],
  ["[/Pattern /DeviceRGB]", "cs", "sc"],
  ["[/Pattern /DeviceRGB]", "CS", "SC"],
] as const)("%s の色空間を%sで選ぶと%sは使用できない", async (definition, selection, operatorName) => {
  const result = await executeColorSpace({
    resources: `<< /ColorSpace << /Pat ${definition} >> >>`,
    content: `/Pat ${selection} ${operatorName}`,
  });

